def p(label,fig,signs,key,trap):return dict(label=label,figure=fig,signs=signs,key=key,trap=trap)
def card(t,s):return '<article class="card"><h2>'+t+'</h2>'+s+'</article>'
def ul(*s):return '<ul>'+''.join('<li>'+x+'</li>'for x in s)+'</ul>'
def table(headers,rows):return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+x+'</th>'for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td data-label="'+headers[j]+'">'+v+'</td>'for j,v in enumerate(r))+'</tr>'for r in rows)+'</tbody></table></div>'
def figure(key):return '<button class="figurebtn" data-figure="'+key+'" aria-label="Увеличить схему">'+F[key]+'</button>'
